1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<meta name="color-scheme" content="light">
7	<title>To-do screen mock-up for approval (CR-2609-823a)</title>
8	<style>
9	  /* ------------------------------------------------------------------
10	     Tokens. Copied verbatim from frontend/src/styles/theme.css (@theme):
11	     the only colours on this page. Every rule below names one of them;
12	     sizes are Tailwind scale steps (multiples of 0.25rem) or these tokens.
13	     theme.css carries one palette (the dark theme was withdrawn,
14	     spec/design/ui/system-states.md § One palette), so this page has none.
15	     ------------------------------------------------------------------ */
16	  :root {
17	    color-scheme: light;
18	    --font-sans: 'Instrument Sans', system-ui, -apple-system, sans-serif;
19	    --font-serif: 'Instrument Serif', Georgia, 'Times New Roman', serif;
20	    --color-ink: #1b1a17;
21	    --color-muted: #5c584f;
22	    --color-faint: #6e6a5f;
23	    --color-disabled: #c4c0b5;
24	    --color-inverse: #f6f5f1;
25	    --color-danger: #a3382c;
26	    --color-accent: #14503a;
27	    --color-accent-strong: #0c3325;
28	    --color-card: #ffffff;
29	    --color-surface: #f6f5f1;
30	    --color-surface-medium: #f1efe8;
31	    --color-hairline: #e2dfd6;
32	    --color-line: #dbd7cc;
33	    --radius-modal: 18px;
34	    --radius-card: 14px;
35	    --radius-control: 10px;
36	    --radius-control-tight: 9px;
37	    --radius-chip: 7px;
38	    --text-meta: 13px;
39	    --text-body: 15px;
40	    --container-reading: 860px;
41	  }
42	
43	  @keyframes rise {
44	    from { opacity: 0; transform: translateY(6px); }
45	    to { opacity: 1; transform: none; }
46	  }
47	
48	  /* ---- Base (frontend/src/index.css) ---- */
49	  *, *::before, *::after { box-sizing: border-box; }
50	  body {
51	    margin: 0;
52	    background: var(--color-surface-medium);
53	    color: var(--color-ink);
54	    font-family: var(--font-sans);
55	    font-size: 1rem;
56	    line-height: 1.5;
57	    -webkit-font-smoothing: antialiased;
58	  }
59	  input, button, textarea { font: inherit; color: inherit; }
60	  button { cursor: pointer; }
61	  :focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
62	  ::placeholder { color: var(--color-faint); opacity: 1; }
63	  .sr-only {
64	    position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
65	    overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
66	  }
67	  .sprite { position: absolute; width: 0; height: 0; overflow: hidden; }
68	
69	  /* ---- The board: chrome around the drawings, not the screen ---- */
70	  .board { max-width: 72rem; margin: 0 auto; padding: 3rem 1rem 6rem; }
71	  @media (min-width: 40rem) { .board { padding-inline: 1.5rem; } }
72	  .board a { color: var(--color-accent); text-underline-offset: 0.125rem; }
73	  .board a:hover { color: var(--color-accent-strong); }
74	  .eyebrow { margin: 0; font-size: var(--text-meta); color: var(--color-faint); letter-spacing: 0.025em; }
75	  .board-title {
76	    margin: 0.5rem 0 0; font-family: var(--font-serif); font-weight: 400;
77	    font-size: 2.25rem; line-height: 1.1; letter-spacing: -0.02em;
78	  }
79	  .board-lede { margin: 0.75rem 0 0; max-width: 48rem; color: var(--color-muted); }
80	  .board-how {
81	    margin: 1rem 0 0; max-width: 48rem; padding: 0.75rem 1rem;
82	    background: var(--color-card); border: 1px solid var(--color-hairline);
83	    border-radius: var(--radius-control); font-size: 0.875rem;
84	  }
85	  .board-how p { margin: 0; }
86	  .board-how p + p { margin-top: 0.375rem; color: var(--color-muted); }
87	  code {
88	    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
89	    font-size: var(--text-meta); background: var(--color-surface-medium);
90	    border-radius: 0.25rem; padding: 0 0.25rem;
91	  }
92	
93	  .notes {
94	    margin-top: 2rem; background: var(--color-card);
95	    border: 1px solid var(--color-hairline); border-radius: var(--radius-card);
96	    padding: 1.5rem;
97	  }
98	  .notes h2 { margin: 0; font-size: 1.25rem; line-height: 1.75rem; letter-spacing: -0.01em; }
99	  .notes h3 {
100	    margin: 2rem 0 0.75rem; font-size: 0.75rem; line-height: 1rem; font-weight: 600;
101	    letter-spacing: 0.05em; text-transform: uppercase; color: var(--color-muted);
102	  }
103	  .notes ul, .notes ol { margin: 0; padding-left: 1.25rem; font-size: 0.875rem; }
104	  .notes li + li { margin-top: 0.375rem; }
105	  .state-list { list-style: none; padding-left: 0 !important; columns: 20rem 3; column-gap: 1.5rem; }
106	  .state-list li { break-inside: avoid; margin-bottom: 0.375rem; }
107	  .state-list li + li { margin-top: 0; }
108	  .table-wrap { overflow-x: auto; }
109	  .choices { width: 100%; min-width: 48rem; border-collapse: collapse; font-size: 0.875rem; }
110	  .choices th, .choices td {
111	    text-align: left; vertical-align: top; padding: 0.625rem 0.75rem;
112	    border-top: 1px solid var(--color-hairline);
113	  }
114	  .choices thead th { border-top: 0; font-size: var(--text-meta); font-weight: 600; color: var(--color-muted); }
115	  .choices td:first-child { white-space: nowrap; font-weight: 600; }
116	  .choices td:nth-child(2) { font-weight: 600; }
117	  .choices td:nth-child(4), .choices td:nth-child(5) { color: var(--color-muted); }
118	  .choices tr:target td { background: var(--color-surface); }
119	
120	  .panel { margin-top: 3.5rem; }
121	  .panel-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.5rem 0.75rem; }
122	  .pid {
123	    font-size: var(--text-meta); font-weight: 600; color: var(--color-inverse);
124	    background: var(--color-ink); border-radius: var(--radius-chip); padding: 0.125rem 0.5rem;
125	  }
126	  .panel-head h2 { margin: 0; font-size: 1.25rem; line-height: 1.75rem; font-weight: 600; letter-spacing: -0.01em; }
127	  .refs { font-size: var(--text-meta); color: var(--color-muted); }
128	  .up { margin-left: auto; font-size: var(--text-meta); }
129	  .drawn, .cap { max-width: 48rem; font-size: 0.875rem; color: var(--color-muted); }
130	  .drawn { margin: 0.5rem 0 1rem; }
131	  .cap { margin: 0.875rem 0 0; }
132	  .drawn b, .cap b, .sub b { color: var(--color-ink); font-weight: 600; }
133	  .sub { margin: 1.5rem 0 0.5rem; max-width: 48rem; font-size: var(--text-meta); color: var(--color-muted); }
134	  .sub:first-of-type { margin-top: 0; }
135	  .cref {
136	    display: inline-block; font-size: var(--text-meta); font-weight: 600;
137	    text-decoration: none; border: 1px solid var(--color-line);
138	    border-radius: var(--radius-chip); padding: 0 0.375rem; margin: 0 0.125rem;
139	    background: var(--color-card);
140	  }
141	  .canvas {
142	    position: relative; background: var(--color-surface);
143	    border: 1px solid var(--color-line); border-radius: var(--radius-modal); overflow: hidden;
144	  }
145	  .canvas.tall { min-height: 28rem; }
146	  .addr {
147	    display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem 1rem;
148	    border-bottom: 1px solid var(--color-hairline); background: var(--color-surface-medium);
149	    font-size: var(--text-meta); color: var(--color-muted);
150	  }
151	  .addr b { color: var(--color-ink); font-weight: 600; }
152	  .elide {
153	    margin: 1rem 0; padding: 0.5rem 0.75rem; border: 1px dashed var(--color-line);
154	    border-radius: var(--radius-control); font-size: var(--text-meta); font-style: italic;
155	    color: var(--color-muted); text-align: center;
156	  }
157	  .variant-label {
158	    position: absolute; top: 0.75rem; right: 1rem; z-index: 1; font-size: var(--text-meta);
159	    font-weight: 600; color: var(--color-muted);
160	  }
161	
162	  /* ---- The frame (frontend/src/components/shell/PageFrame.tsx) ---- */
163	  .fr { padding: 0 1.5rem 3rem; }
164	  .fr-full { padding-bottom: 6rem; }
165	  .fr-crop { padding-bottom: 1.25rem; }
166	  .fr.has-toast { padding-bottom: 6rem; }
167	  .fr-col { max-width: var(--container-reading); margin: 0 auto; }
168	  .fr-head {
169	    display: flex; align-items: center; justify-content: space-between;
170	    flex-wrap: wrap; gap: 0.75rem 1rem; padding-top: 1.75rem;
171	  }
172	  .fr-strip { padding-bottom: 1.75rem; }
173	  .fr-left { display: flex; align-items: center; flex-wrap: wrap; gap: 0.75rem 2rem; }
174	  .board .lockup { display: flex; align-items: center; gap: 0.625rem; color: var(--color-ink); text-decoration: none; }
175	  .board .lockup:hover { color: var(--color-ink); }
176	  .lockup-mark {
177	    display: flex; align-items: center; justify-content: center;
178	    width: 1.625rem; height: 1.625rem; border-radius: var(--radius-chip);
179	    background: var(--color-accent); color: var(--color-inverse);
180	    font-size: var(--text-meta); font-weight: 600;
181	  }
182	  .lockup-name { font-size: 0.875rem; font-weight: 500; letter-spacing: -0.01em; }
183	  .fr-nav { display: flex; gap: 1.25rem; font-size: 0.875rem; }
184	  .board .fr-nav a { color: var(--color-muted); text-decoration: none; }
185	  .board .fr-nav a:hover { color: var(--color-ink); }
186	  .board .fr-nav a[aria-current="page"] {
187	    color: var(--color-ink); font-weight: 500; text-decoration: underline;
188	    text-decoration-thickness: 2px; text-underline-offset: 0.375rem;
189	  }
190	  .fr-meta { font-size: var(--text-meta); color: var(--color-muted); font-variant-numeric: tabular-nums; }
191	  .fr-title {
192	    display: flex; flex-direction: column; gap: 0.625rem;
193	    border-bottom: 1px solid var(--color-hairline); padding: 3.5rem 0 2.5rem;
194	  }
195	  .t-h1 {
196	    margin: 0; font-family: var(--font-serif); font-weight: 400;
197	    font-size: clamp(2.5rem, 7vw, 4.25rem); line-height: 1.02; letter-spacing: -0.02em;
198	  }
199	  .t-lede { margin: 0; max-width: 44ch; font-size: 1rem; line-height: 1.55; color: var(--color-muted); text-wrap: pretty; }
200	  .fr-foot { padding-top: 4rem; font-size: 0.75rem; line-height: 1rem; color: var(--color-faint); }
201	
202	  /* ---- The add field (TodoTaskComposer) ---- */
203	  .composer-sec { padding: 1.75rem 0 1.25rem; }
204	  .composer {
205	    display: flex; flex-direction: column; gap: 0.5rem; background: var(--color-card);
206	    border: 1px solid var(--color-hairline); border-radius: var(--radius-card);
207	    padding: 0.75rem 0.75rem 0.75rem 1.125rem;
208	  }
209	  .composer-row { display: flex; align-items: center; gap: 0.75rem; }
210	  .composer-field { flex: 1; min-width: 0; display: flex; }
211	  .composer-input {
212	    width: 100%; border: 0; background: transparent; padding: 0;
213	    font-size: 1rem; line-height: 1.5rem; color: var(--color-ink);
214	  }
215	  .composer-input:disabled, .editor-input:disabled { color: var(--color-muted); cursor: progress; }
216	  .is-focused { outline: 2px solid var(--color-accent); outline-offset: 2px; }
217	  .btn-add {
218	    flex: none; border: 0; border-radius: var(--radius-control); background: var(--color-accent);
219	    color: var(--color-inverse); padding: 0.625rem 1.25rem;
220	    font-size: 0.875rem; line-height: 1.25rem; font-weight: 500;
221	  }
222	  .btn-add:hover:not(:disabled) { filter: brightness(1.12); }
223	  .btn-add:disabled { opacity: 0.35; cursor: not-allowed; }
224	  .field-error { font-size: 0.75rem; line-height: 1rem; font-weight: 500; color: var(--color-danger); }
225	
226	  /* ---- The list and a task's row (TodoTaskRow, Checkbox) ---- */
227	  .tasks {
228	    list-style: none; margin: 0; padding: 0; background: var(--color-card);
229	    border: 1px solid var(--color-hairline); border-radius: var(--radius-card); overflow: hidden;
230	  }
231	  .task { display: flex; align-items: flex-start; gap: 1rem; padding: 0.875rem 1.25rem; }
232	  .task + .task { border-top: 1px solid var(--color-hairline); }
233	  .task.rise { animation: rise 0.28s ease both; }
234	  .task-main {
235	    position: relative; display: flex; align-items: flex-start; gap: 0.75rem;
236	    flex: 1; min-width: 0; cursor: pointer;
237	  }
238	  .task-main-box { flex: none; }
239	  .task-input {
240	    position: absolute; left: 0; top: 0.125rem; width: 1.25rem; height: 1.25rem;
241	    margin: 0; opacity: 0; cursor: pointer;
242	  }
243	  .task-input:disabled { cursor: progress; }
244	  .box {
245	    flex: none; display: flex; align-items: center; justify-content: center;
246	    width: 1.25rem; height: 1.25rem; margin-top: 0.125rem;
247	    border: 2px solid var(--color-faint); border-radius: 0.375rem; background: var(--color-card);
248	  }
249	  .box svg {
250	    width: 0.875rem; height: 0.875rem; fill: none; stroke: var(--color-inverse);
251	    stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; opacity: 0;
252	  }
253	  .task-input:checked + .box { background: var(--color-accent); border-color: var(--color-accent); }
254	  .task-input:checked + .box svg { opacity: 1; }
255	  .task-input:focus-visible + .box { outline: 2px solid var(--color-accent); outline-offset: 2px; }
256	  .task-input:disabled + .box { opacity: 0.5; }
257	  .task-text { min-width: 0; font-size: 1rem; line-height: 1.5rem; overflow-wrap: anywhere; }
258	  .task-input:checked ~ .task-text { text-decoration-line: line-through; color: var(--color-muted); }
259	  .marker { flex: none; font-size: var(--text-meta); line-height: 1.5rem; color: var(--color-faint); }
260	  .task-actions { flex: none; display: flex; gap: 0.875rem; line-height: 1.5rem; }
261	  .act {
262	    border: 0; background: transparent; padding: 0; font-size: var(--text-meta);
263	    line-height: 1.5rem; color: var(--color-faint);
264	  }
265	  .act-edit:hover:not(:disabled) { color: var(--color-accent); }
266	  .act-del:hover:not(:disabled) { color: var(--color-danger); }
267	  .act:disabled { opacity: 0.5; cursor: default; }
268	  .task-elide {
269	    justify-content: center; background: var(--color-surface); font-size: var(--text-meta);
270	    font-style: italic; color: var(--color-muted);
271	  }
272	
273	  /* ---- Editing in place ---- */
274	  .editor { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 0.75rem; }
275	  .editor-field { display: flex; }
276	  .editor-input {
277	    width: 100%; border: 1px solid var(--color-hairline); border-radius: var(--radius-control-tight);
278	    background: var(--color-card); padding: 0.5rem 0.75rem; font-size: 1rem; line-height: 1.5rem;
279	    color: var(--color-ink);
280	  }
281	  .editor-input:disabled { background: var(--color-surface); }
282	  .editor-actions { display: flex; gap: 0.5rem; }
283	  .btn-save {
284	    border: 0; border-radius: var(--radius-control-tight); background: var(--color-accent);
285	    color: var(--color-inverse); padding: 0.5rem 1rem; font-size: var(--text-meta); font-weight: 500;
286	  }
287	  .btn-save:hover:not(:disabled) { filter: brightness(1.15); }
288	  .btn-save:disabled { opacity: 0.35; cursor: not-allowed; }
289	  .btn-cancel {
290	    border: 1px solid var(--color-hairline); border-radius: var(--radius-control-tight);
291	    background: transparent; color: var(--color-muted); padding: 0.5rem 1rem; font-size: var(--text-meta);
292	  }
293	  .btn-cancel:hover:not(:disabled) { background: var(--color-surface-medium); }
294	  .btn-cancel:disabled { opacity: 0.5; cursor: default; }
295	
296	  /* ---- Empty, loading, failed ---- */
297	  .empty {
298	    border: 1px dashed var(--color-line); border-radius: var(--radius-card);
299	    padding: 3.5rem 1.25rem; text-align: center; font-size: var(--text-body); color: var(--color-muted);
300	  }
301	  .task-skel { align-items: center; }
302	  .skel { display: block; border-radius: 0.375rem; background: var(--color-surface-medium); }
303	  .skel-box { flex: none; width: 1.25rem; height: 1.25rem; }
304	  .skel-bar { height: 0.625rem; }
305	  .w-2-5 { width: 40%; } .w-1-2 { width: 50%; } .w-3-5 { width: 60%; } .w-4-5 { width: 80%; }
306	  .read-failed { margin: 0 0 1rem; font-size: var(--text-meta); color: var(--color-muted); }
307	  .err {
308	    border: 1px solid var(--color-hairline); border-radius: var(--radius-card);
309	    background: var(--color-card); padding: 2rem 1.5rem; text-align: center;
310	  }
311	  .err-title { margin: 0; font-size: 1rem; font-weight: 700; }
312	  .err-detail { margin: 0.5rem auto 0; max-width: 42rem; font-size: 0.875rem; line-height: 1.625; color: var(--color-muted); }
313	  .err-actions { margin-top: 0.875rem; display: flex; justify-content: center; }
314	
315	  /* ---- Buttons (frontend/src/components/ui/Button.tsx) ---- */
316	  .btn-outlined, .btn-quiet, .btn-primary, .btn-link-primary {
317	    display: inline-flex; align-items: center; justify-content: center; height: 2.125rem;
318	    padding: 0 1rem; border-radius: var(--radius-control); font-size: 0.875rem; font-weight: 500;
319	    white-space: nowrap;
320	  }
321	  .btn-outlined { border: 1px solid var(--color-hairline); background: var(--color-card); color: var(--color-ink); }
322	  .btn-outlined:hover { border-color: var(--color-accent); color: var(--color-accent); }
323	  .btn-quiet { border: 1px solid transparent; background: transparent; color: var(--color-muted); }
324	  .btn-quiet:hover:not(:disabled) { background: var(--color-surface-medium); color: var(--color-ink); }
325	  .btn-quiet:disabled { color: var(--color-disabled); cursor: default; }
326	  .btn-primary { border: 1px solid var(--color-accent); background: var(--color-accent); color: var(--color-inverse); }
327	  .btn-primary:hover:not(:disabled) { filter: brightness(1.12); }
328	  .btn-primary:disabled { opacity: 0.35; cursor: default; }
329	  .board .btn-link-primary {
330	    border: 1px solid var(--color-accent); background: var(--color-accent);
331	    color: var(--color-inverse); text-decoration: none;
332	  }
333	  .nf-actions { display: flex; justify-content: center; padding-top: 2.5rem; }
334	
335	  /* ---- Toasts (frontend/src/components/ui/Toast.tsx) ---- */
336	  .toasts {
337	    position: absolute; right: 1.25rem; bottom: 1.25rem; z-index: 2;
338	    display: flex; flex-direction: column; gap: 0.5rem; max-width: calc(100% - 2.5rem);
339	  }
340	  .toast {
341	    display: flex; align-items: flex-start; gap: 0.625rem; max-width: 28rem;
342	    border-radius: 0.75rem; background: var(--color-ink); color: var(--color-inverse);
343	    padding: 0.625rem 0.875rem; font-size: 0.75rem; line-height: 1.625; font-weight: 700;
344	    box-shadow:
345	      0 1.25rem 1.5625rem -0.3125rem color-mix(in srgb, var(--color-ink) 10%, transparent),
346	      0 0.5rem 0.625rem -0.375rem color-mix(in srgb, var(--color-ink) 10%, transparent);
347	  }
348	  .glyph { flex: none; font-weight: 700; }
349	  .glyph-ok { color: var(--color-inverse); }
350	  .glyph-err { color: var(--color-danger); }
351	  .toast-msg { flex: 1; min-width: 0; }
352	  .toast-x {
353	    flex: none; border: 0; background: transparent; padding: 0 0.25rem; border-radius: 9999px;
354	    font-size: 0.875rem; font-weight: 700;
355	    color: color-mix(in srgb, var(--color-inverse) 60%, transparent);
356	  }
357	  .toast-x:hover { color: var(--color-inverse); }
358	
359	  /* ---- The delete question (DeleteTodoTaskDialog over Modal.tsx) ---- */
360	  .backdrop {
361	    position: absolute; inset: 0; z-index: 3; display: flex; align-items: center;
362	    justify-content: center; padding: 1.5rem;
363	    background: color-mix(in srgb, var(--color-ink) 45%, transparent);
364	  }
365	  .dialog {
366	    display: flex; flex-direction: column; width: 100%; max-width: 36rem; overflow: hidden;
367	    border: 1px solid var(--color-hairline); border-radius: var(--radius-modal);
368	    background: var(--color-card);
369	    box-shadow: 0 1.5625rem 3.125rem -0.75rem color-mix(in srgb, var(--color-ink) 25%, transparent);
370	  }
371	  .dialog-head { border-bottom: 1px solid var(--color-hairline); padding: 0.875rem 1.25rem; }
372	  .dialog-title { margin: 0; font-size: 1.125rem; line-height: 1.75rem; font-weight: 700; }
373	  .dialog-body { padding: 0.875rem 1.25rem; }
374	  .quote {
375	    margin: 0; border-radius: 0.75rem; background: var(--color-surface);
376	    padding: 0.625rem 0.75rem; font-size: 0.875rem; overflow-wrap: anywhere;
377	  }
378	  .dialog-foot {
379	    display: flex; align-items: center; flex-wrap: wrap; gap: 0.625rem;
380	    border-top: 1px solid var(--color-hairline); padding: 0.75rem 1.25rem;
