def check_deltas(root: pathlib.Path | None = None) -> Outcome:
    root = root or REPO_ROOT
    problems: list[Problem] = []
    documents = entries = 0
    found = sorted((root / "spec" / "changes").glob("CR-*/delta.md")) + sorted(
        (root / "spec" / "changes").glob("CR-*/delta-history.md")
    )
    for path in found:
        if scaffold.is_template(path):
            continue
        documents += 1
        relative = _relative(path, root)
        lines = path.read_text(encoding="utf-8").splitlines()

        for number, line in enumerate(lines, start=1):
            if not _DELTA_ENTRY.match(line):
                continue
            entries += 1
            reason = why_reason(lines, number - 1)
            if reason is None:
                problems.append(Problem("delta", relative, number, "entry has no '**Why:**'."))
            elif len(reason) < _MIN_WHY:
                problems.append(
                    Problem(
                        "delta",
                        relative,
                        number,
                        f"'**Why:**' is under {_MIN_WHY} characters. A reason that short is "
                        "almost always a restatement of the change.",
                    )
                )
    return Outcome(
